#include "model.hpp"
#include <set>
namespace pe {
void World::validate(const State&s){require(s.people.size()==5&&s.territory.locations.size()==6,"Invalid fixture cardinality");require(s.tick>=0&&s.tick<=1000000&&s.next_event>0&&s.next_request>0&&s.revision<1000000000000ULL,"Invalid clock/sequence");Money total=s.government.account.money;require(total>=0&&total<=1000000000,"Invalid treasury");require(s.government.id==100&&s.government.account.id==100&&(s.government.office.holder>=0&&s.government.office.holder<=5)&&s.government.office.can_grant==(s.government.office.holder!=0),"Invalid government");std::set<int>slots;contracts::validate(s);
 auto inv=[](const Inventory&i){for(int n:i.units)require(n>=0&&n<=1000000,"Invalid inventory");};inv(s.government.account.inventory);
 for(int id=1;id<=5;++id){const auto&p=person(s,id);require(p.id==id&&p.account.id==id,"Account identity mismatch");location(s,p.location);require(p.account.money>=0&&p.account.money<=1000000000,"Invalid account balance");inv(p.account.inventory);total+=p.account.money;const auto&a=p.activity;require(int(a.kind)>=0&&int(a.kind)<=int(ActivityKind::Care),"Invalid activity type");require(std::isfinite(a.progress)&&std::isfinite(a.required)&&a.progress>=0&&a.required>=0&&a.required<=1000,"Invalid activity progress");require(a.escrow>=0&&a.escrow<=1000000,"Invalid escrow");total+=a.escrow;inv(a.reserved);
 for(double n:{p.body.hunger,p.body.thirst,p.body.fatigue,p.body.health,p.body.joy})require(std::isfinite(n)&&n>=0&&n<=100,"Invalid body value");
 for(double n:{p.experience.farming,p.experience.crafting,p.experience.communication})require(std::isfinite(n)&&n>=0&&n<=1000000,"Invalid experience");
 for(int n:{p.tendencies.security,p.tendencies.pleasure,p.tendencies.mobility})require(n>=0&&n<=100,"Invalid tendency");
 require(p.name.size()<=160&&p.goal.size()<=160,"Invalid person text");for(auto&[other,v]:p.relations){person(s,other);require(v>=0&&v<=100,"Invalid relation");}
 if(a.kind!=ActivityKind::Idle){require(a.required>0&&a.progress<a.required,"Invalid active progress");if(a.kind==ActivityKind::Work){const auto&l=location(s,a.target);require(a.target==11||a.target==12,"Invalid work site");require(p.location==a.target&&a.escrow==(a.option==1?0:l.wage)&&slots.insert(a.target).second&&!l.job,"Invalid work commitment");}else require(a.escrow==0,"Unexpected escrow");if(a.kind==ActivityKind::Move)location(s,a.target);if(a.kind==ActivityKind::Talk){const auto&q=person(s,a.target);require(q.activity.kind==ActivityKind::Talk&&q.activity.target==id&&q.activity.option==a.option&&q.location==p.location,"Broken conversation pair");}}
 else require(a.escrow==0,"Idle escrow");
 Inventory expected_reserved;
 if(a.kind==ActivityKind::Work){bool farm=a.target==11;expected_reserved[farm?Good::Seed:Good::Wood]=farm?1:2;require(a.required==(farm?6:8)&&(a.option==0||a.option==1)&&((a.option==1)==(id==location(s,a.target).owner)),"Invalid work terms");require(location(s,a.target).tool&&location(s,a.target).tool_uses>0,"Work without tool");}
 else if(a.kind==ActivityKind::Meal){require(a.option==0||a.option==1,"Invalid meal option");expected_reserved[Good::Food]=a.option+1;require(a.required==(a.option?3:1)&&a.target==p.location,"Invalid meal terms");}
 else if(a.kind==ActivityKind::Drink){expected_reserved[Good::Water]=1;require(a.target==p.location&&a.required==1&&(a.option==0||a.option==1)&&(a.option==1||p.location==14),"Invalid drinking terms");}
 else if(a.kind==ActivityKind::Rest){auto&home=location(s,p.location);require(a.target==p.location&&a.required==3&&contracts::residence_at(s,id,home.id,a.started),"Invalid residence activity");}
 else if(a.kind==ActivityKind::Move)require(a.required==1&&a.target!=p.location,"Invalid travel terms");
 else if(a.kind==ActivityKind::Study)require(p.location==10&&a.target==10&&a.required==2,"Invalid study terms");
 else if(a.kind==ActivityKind::Talk){require(a.required==1||a.required==2,"Invalid talk terms");auto&other=person(s,a.target);require(other.activity.required==a.required&&other.activity.progress==a.progress,"Conversation progress mismatch");require(std::any_of(s.requests.begin(),s.requests.end(),[&](const Request&r){return r.id==a.option&&r.status==1&&((r.from==id&&r.to==a.target)||(r.to==id&&r.from==a.target));}),"Conversation lacks accepted request");}
 if(a.kind==ActivityKind::Collect){expected_reserved[Good::Water]=1;require(p.location==14&&a.target==14&&a.required==1,"Invalid collection terms");}
 if(a.kind==ActivityKind::Care){expected_reserved[Good::Food]=1;expected_reserved[Good::Water]=1;require(p.location==a.target&&a.required==6&&contracts::residence_at(s,id,a.target,a.started),"Invalid care terms");}
 require(a.started>=0&&a.started<=s.tick,"Invalid activity start");
 require(a.reserved.units==expected_reserved.units,"Invalid activity reservation");
 for(const auto&f:p.knowledge){require(f.event>0&&f.event<s.next_event&&f.happened>=0&&f.happened<=f.received&&f.received<=s.tick&&f.text.size()<=2000,"Invalid fact");person(s,f.source);}
 }
 total+=contracts::escrow_total(s);require(total==s.initial_money&&s.initial_money==556,"Money conservation violated");
 for(int id=10;id<=15;++id){const auto&l=location(s,id);require(l.id==id,"Invalid site identity");if(l.owner!=100)person(s,l.owner);inv(l.stock);require(l.wage>=1&&l.wage<=100,"Invalid job wage");require(l.tool_uses>=0&&l.tool_uses<=12&&(l.tool||l.tool_uses==0),"Invalid installed tool");for(Id resident:l.residents)person(s,resident);}
 Inventory holdings=s.government.account.inventory;Inventory contract_stock=contracts::reserved_total(s);for(int i=0;i<goods;++i)holdings.units[i]+=contract_stock.units[i];for(auto&[id,l]:s.territory.locations)if(l.tool)++holdings[Good::Tool];for(auto&[id,p]:s.people)for(int i=0;i<goods;++i)holdings.units[i]+=p.account.inventory.units[i]+p.activity.reserved.units[i];for(auto&[id,l]:s.territory.locations)for(int i=0;i<goods;++i)holdings.units[i]+=l.stock.units[i];inv(s.created);inv(s.consumed);int initial[]={6,20,12,4,120};for(int i=0;i<goods;++i)require(holdings.units[i]+s.consumed.units[i]==initial[i]+s.created.units[i],"Goods conservation violated");
 require(s.events.size()<=20000&&s.requests.size()<=2000,"History capacity exceeded");int prev=0;for(auto&e:s.events){require(e.id>prev&&e.id<s.next_event&&e.tick>=0&&e.tick<=s.tick&&e.text.size()<=2000,"Invalid event");for(Id id:e.witnesses)person(s,id);prev=e.id;}
 prev=0;for(auto&r:s.requests){require(r.id>prev&&r.id<s.next_request&&r.status>=0&&r.status<=3&&r.from!=r.to,"Invalid request");person(s,r.from);person(s,r.to);if(r.status==1){auto&a=person(s,r.from).activity;require(a.kind==ActivityKind::Talk&&a.target==r.to&&a.option==r.id,"Accepted request lacks participants");}prev=r.id;}
}
}
